Translate("esMX", "durotar", {
	title = "Durotar",
	sections = {
		{
			title = "Resumen",
			text = [=[Durotar es la patria de los orcos, un país rojo y quebrado en la costa oriental de {link:kalimdor}Kalimdor{/link}. Su suelo está agrietado y seco, sus cañones son abruptos y el sol cae sobre él sin piedad. Los orcos lo eligieron de buen grado, pues su áspera belleza les recuerda el mundo que perdieron. Aquí el Jefe de Guerra {link:thrall}Thrall{/link} ha levantado su capital, {link:orgrimmar}Orgrimmar{/link}, y aquí se pone a prueba a los jóvenes de la {link:horde}Horda{/link} antes de enviarlos al mundo. Es una tierra en paz solo de nombre. Los enemigos la vigilan desde el mar, desde los cañones y desde las sombras de sus propias cuevas.]=],
		},
		{
			title = "Orígenes",
			text = [=[Antes de la llegada de los orcos, estas tierras se contaban como parte de {link:the-barrens}Los Baldíos{/link}, y los {link:quilboar}jabaespines{/link} de la tribu Crines de Acero las recorrían a sus anchas. Tras la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}, {link:thrall}Thrall{/link} condujo a su pueblo al este, hasta la costa, y reclamó la tierra entre el Río Furia del Sur y el mar. La llamó Durotar en honor de su padre, Durotan, jefe del {link:frostwolf-clan}clan Lobo Gélido{/link}. Los {link:tauren}tauren{/link} y los {link:darkspear-trolls}trols Lanza Negra{/link} prestaron su fuerza a la nueva nación, y los orcos expulsaron a los Crines de Acero de todo salvo los bordes occidentales de la tierra.]=],
		},
		{
			title = "El presente",
			text = [=[Durotar es el corazón de la nueva {link:horde}Horda{/link}. Aun así, su paz es frágil. Los humanos de {link:kul-tiras}Kul Tiras{/link} aún ocupan las ruinas del {link:tiragarde-keep}Fuerte de Tiragarde{/link} en la costa oriental. El médico brujo {link:zalazane}Zalazane{/link} gobierna las {link:echo-isles}Islas del Eco{/link} mediante un vudú oscuro. Los Crines de Acero presionan desde el oeste, los {link:centaurs}centauros{/link} {link:kolkar-centaurs}Kolkar{/link} conspiran en su risco y las {link:harpies}arpías{/link} Viento Seco acechan a las caravanas. Lo peor de todo es que los sectarios del {link:burning-blade}Filo Ardiente{/link} se esconden en las cuevas de Durotar, cerca de las mismas puertas de la capital. Últimamente, incluso se ha visto a los {link:naga}nagas{/link} a lo largo de la costa norte.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Los orcos.{/b} Cultivan la tierra dura, vigilan desde {link:razor-hill}Cerrotajo{/link} y adiestran a sus jóvenes en el {link:valley-of-trials}Valle de los Retos{/link}.
• {b}Los trols {link:darkspear-trolls}Lanza Negra{/link}.{/b} Expulsados de sus islas, han construido un poblado de pescadores en la costa sur y esperan el día en que puedan volver a casa.
• {b}Los goblins.{/b} Comerciantes de {link:ratchet}Trinquete{/link} que llevan caravanas por los caminos.
• {b}Los jabaespines Crines de Acero.{/b} Se aferran a sus campamentos de zarzas en el oeste y juran recuperar la tierra.
• {b}Los humanos de {link:kul-tiras}Kul Tiras{/link}.{/b} Marineros e infantes de marina que sirven a la memoria de su almirante muerto.
• {b}El {link:burning-blade}Filo Ardiente{/link}.{/b} Adoradores de demonios escondidos en las cuevas.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}El desembarco.{/b} Tras la guerra contra la {link:burning-legion}Legión Ardiente{/link}, los orcos construyeron {link:orgrimmar}Orgrimmar{/link} y empezaron a domar la tierra que la rodea.
• {b}La guerra del almirante.{/b} Poco después, el gran almirante {link:daelin-proudmoore}Daelin Proudmoore{/link} zarpó de {link:kul-tiras}Kul Tiras{/link} con una gran flota, decidido a acabar con los orcos. Sus hombres levantaron el {link:tiragarde-keep}Fuerte de Tiragarde{/link} en la costa. El fuerte cayó, y el propio almirante murió ante los muros de {link:theramore-isle}Theramore{/link}.
• {b}El traidor de las islas.{/b} Los {link:darkspear-trolls}Lanza Negra{/link} se asentaron en las {link:echo-isles}Islas del Eco{/link}, pero uno de sus propios médicos brujos, {link:zalazane}Zalazane{/link}, volvió su magia contra ellos y empujó a los trols libres al continente.]=],
		},
		{
			title = "Tradiciones de la tierra roja",
			text = [=[• Los aspirantes a chamán de la {link:horde}Horda{/link} beben un brebaje sagrado llamado sapta en la {link:spirit-rock}Roca de los Espíritus{/link}, muy por encima del {link:valley-of-trials}Valle de los Retos{/link}, y allí se presentan ante el espíritu de la tierra.
• Los restos de la flota de Proudmoore siguen en los bajíos al este del {link:tiragarde-keep}Fuerte de Tiragarde{/link}. Los orcos de {link:razor-hill}Cerrotajo{/link} envían nadadores a registrarlos en busca de herramientas humanas.
• Una madre de la Granja Tor'kren esperó muchos días a su hijo, que había ido a cazar los crocoliscos del Río Furia del Sur. No volvió.]=],
		},
	},
})

Translate("esMX", "valley-of-trials", {
	title = "Valle de los Retos",
	sections = {
		{
			title = "Resumen",
			text = [=[El Valle de los Retos se encuentra en el suroeste de {link:durotar}Durotar{/link}, cercado por acantilados rojos. Es el campo de pruebas de la {link:horde}Horda{/link}. Los jóvenes orcos y trols vienen aquí a enfrentarse a sus primeros enemigos: los jabalíes del fondo del valle, los escórpidos de las laderas del norte y un escórpido monstruoso llamado Sarkoth. Los instructores de la Horda tienen su campamento en una cueva conocida como El Cubil. Los peones talan los pocos árboles del valle para obtener madera, cuando no están dormidos. Últimamente el valle se ha vuelto más peligroso, pues el {link:burning-blade}Filo Ardiente{/link} ha establecido un aquelarre en las cuevas de su pared norte.]=],
		},
	},
})

Translate("esMX", "burning-blade-coven", {
	title = "Aquelarre del Filo Ardiente",
	sections = {
		{
			title = "Resumen",
			text = [=[El Aquelarre del Filo Ardiente es una cueva en los acantilados al norte del {link:valley-of-trials}Valle de los Retos{/link}. En otro tiempo los mineros la exploraron en busca de mineral. Ahora la han reclamado los sectarios del {link:burning-blade}Filo Ardiente{/link}, y sus pequeños demonios, los familiares viles, salen en tropel por su boca hacia el valle. En lo más hondo, entre cámaras de agua que cae, el brujo {link:yarrog-baneshadow}Yarrog Baneshadow{/link} guarda un medallón de poder oscuro. El aquelarre es pequeño, pero su presencia tan cerca del campo de pruebas de la {link:horde}Horda{/link} advierte de que la secta llega más lejos de lo que nadie quisiera.]=],
		},
	},
})

Translate("esMX", "spirit-rock", {
	title = "Roca de los Espíritus",
	aliases = { "Sendero Oculto" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Roca de los Espíritus se alza en las colinas, muy por encima del {link:valley-of-trials}Valle de los Retos{/link}, al final de un estrecho sendero llamado el Sendero Oculto. Es tierra sagrada para los chamanes de la {link:horde}Horda{/link}. Aquí los jóvenes que quieren seguir el camino del chamán beben la sapta, un brebaje que une el espíritu a los {link:elements}elementos{/link}, y aquí ven por primera vez con sus propios ojos al espíritu de la tierra. El rito debe hacerse en un lugar sagrado, y en ningún otro. Pocos que no sean chamanes suben alguna vez el Sendero Oculto.]=],
		},
	},
})

Translate("esMX", "razor-hill", {
	title = "Cerrotajo",
	aliases = { "Cuartel de Cerrotajo" },
	sections = {
		{
			title = "Resumen",
			text = [=[Cerrotajo es la encrucijada de {link:durotar}Durotar{/link}. Sus caminos van al norte hacia {link:orgrimmar}Orgrimmar{/link}, al sur hacia el {link:valley-of-trials}Valle de los Retos{/link} y el {link:sen-jin-village}Poblado Sen'jin{/link}, y al oeste, cruzando el río, hacia {link:the-barrens}Los Baldíos{/link}. Es un pueblo de soldados. Desde su cuartel, {link:gar-thok}Gar'Thok{/link} dirige la defensa de la tierra, y {link:orgnil-soulscar}Orgnil Soulscar{/link} da caza a los sectarios del {link:burning-blade}Filo Ardiente{/link}. Un viejo guerrero guarda un cuerno de señales en la atalaya que domina el pueblo. Lo hace sonar menos a menudo que antes, y se alegra de ello.]=],
		},
	},
})

Translate("esMX", "sen-jin-village", {
	title = "Poblado Sen'jin",
	sections = {
		{
			title = "Resumen",
			text = [=[El Poblado Sen'jin es el hogar de los {link:darkspear-trolls}Lanza Negra{/link} libres en la costa sur de {link:durotar}Durotar{/link}. Los trols lo construyeron tras ser expulsados de las {link:echo-isles}Islas del Eco{/link}, y le dieron el nombre de Sen'jin, el jefe que dio su vida para que su pueblo pudiera seguir a los orcos a una nueva tierra. Es un poblado de chozas y muelles de pesca. Sus ancianos son médicos brujos y alquimistas, sus jóvenes son cazadores, y sus cuidadores de raptores crían bestias de las islas salvajes. Desde su orilla, los trols pueden ver las islas que han perdido.]=],
		},
	},
})

Translate("esMX", "echo-isles", {
	title = "Islas del Eco",
	sections = {
		{
			title = "Resumen",
			text = [=[Las Islas del Eco se encuentran frente a la costa sureste de {link:durotar}Durotar{/link}. Debían ser el nuevo hogar de los {link:darkspear-trolls}Lanza Negra{/link}. Ahora pertenecen al médico brujo {link:zalazane}Zalazane{/link}, que tiene sometidos con sus maleficios a los trols de las islas. Sus esclavos vagan entre las chozas, y sus montones de ju-ju enturbian el flujo de la magia por toda la tierra. Raptores Bloodtalon y tigres rayados cazan en la jungla. En la isla más grande, un círculo de cráneos retiene los espíritus atrapados de los trols que lo desafiaron.]=],
		},
	},
})

Translate("esMX", "tiragarde-keep", {
	title = "Fuerte de Tiragarde",
	sections = {
		{
			title = "Resumen",
			text = [=[El Fuerte de Tiragarde se alza en la costa oriental de {link:durotar}Durotar{/link}. Lo levantaron los marineros del almirante {link:daelin-proudmoore}Daelin Proudmoore{/link} cuando su flota vino a destruir a la {link:horde}Horda{/link}. Los orcos tomaron el fuerte y rompieron sus muros. Sin embargo, tras la muerte del almirante, una fuerza de reserva al mando del teniente {link:lieutenant-benedict}Benedict{/link} regresó y fortificó de nuevo las ruinas. Los infantes de marina de {link:kul-tiras}Kul Tiras{/link} aún ondean allí su estandarte. Entre los escombros que rodean el fuerte yacen las armas de los orcos que cayeron en el primer asalto, y los suyos quieren verlas honradas.]=],
		},
	},
})

Translate("esMX", "skull-rock", {
	title = "Roca del Cráneo",
	sections = {
		{
			title = "Resumen",
			text = [=[La Roca del Cráneo es una cueva en las montañas al este de las puertas de {link:orgrimmar}Orgrimmar{/link}. Es una guarida del {link:burning-blade}Filo Ardiente{/link}. Los sectarios de su interior practican ritos inmundos y se queman la carne con collares abrasadores, que los atan al poder demoníaco. Su amo en la cueva es el brujo {link:gazz-uz}Gazz'uz{/link}, que responde ante una voz que habla a través de un colgante de sombra ardiente. Que la secta pueda esconderse tan cerca de los muros del Jefe de Guerra inquieta a todos los soldados de la {link:horde}Horda{/link}.]=],
		},
	},
})

Translate("esMX", "drygulch-ravine", {
	title = "Barranco Árido",
	aliases = { "Cañón del Ventajo" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Cañón del Ventajo atraviesa las colinas entre {link:razor-hill}Cerrotajo{/link} y {link:orgrimmar}Orgrimmar{/link}, y tras una cueva en su lado oriental se encuentra la garganta oculta del Barranco Árido. Ambos pertenecen a las {link:harpies}arpías{/link} Viento Seco. Se abalanzan sobre las caravanas goblins del camino, se llevan sus mercancías y las acumulan en sus nidos de los acantilados. Las más fuertes de la bandada guardan sus huevos en el barranco. Algunas de las brujas de las arpías han empezado a jugar con una extraña magia de tormenta.]=],
		},
	},
})

Translate("esMX", "thunder-ridge", {
	title = "Monte del Trueno",
	sections = {
		{
			title = "Resumen",
			text = [=[El Monte del Trueno es una garganta boscosa en el noroeste de {link:durotar}Durotar{/link}, al sur de {link:orgrimmar}Orgrimmar{/link}. Debe su nombre a los lagartos del trueno que la recorren, grandes bestias cuyos cuerpos guardan una carga de rayo. El brujo goblin Fizzle Darkstorm ha instalado allí un campamento con sectarios del {link:burning-blade}Filo Ardiente{/link}, y siembran el caos entre los árboles. Los orcos cazan a los lagartos por sus pieles, que cubren los tejados de la creciente capital. El más poderoso de ellos se llama Halikor, y su pezuña es un trofeo digno de presumir.]=],
		},
	},
})

Translate("esMX", "kolkar-crag", {
	title = "Risco Kolkar",
	sections = {
		{
			title = "Resumen",
			text = [=[El Risco Kolkar es una garganta rocosa en el sur de {link:durotar}Durotar{/link}, al oeste del {link:sen-jin-village}Poblado Sen'jin{/link}. Los {link:centaurs}centauros{/link} {link:kolkar-centaurs}Kolkar{/link} han hecho de él su campamento. Atacan de noche, y su señor de la guerra, Kolkanis, ha trazado planes para golpear a los orcos y trols de la tierra. Un explorador trol de la {link:horde}Horda{/link} se coló una vez en el risco y leyó esos planes con sus propios ojos. Otros que han intentado explorar el risco solos no siempre han vuelto a salir.]=],
		},
	},
})

Translate("esMX", "razormane-grounds", {
	title = "Tierras Crines de Acero",
	sections = {
		{
			title = "Resumen",
			text = [=[Las Tierras Crines de Acero se encuentran en el oeste de {link:durotar}Durotar{/link}, donde la tierra desciende hacia el Río Furia del Sur. Aquí tienen sus campamentos de zarzas los {link:quilboar}jabaespines{/link} de la tribu Crines de Acero. Dominaban gran parte de Durotar antes de que llegaran los orcos, y nunca han aceptado su pérdida. Huesos pelados cubren el suelo en torno a sus espinos. Sus geomantes invocan a la tierra, y su guardia de batalla defiende los campamentos con una furia nacida del orgullo herido. Los orcos de {link:razor-hill}Cerrotajo{/link} han jurado expulsarlos de Durotar, y después, quizá, de {link:kalimdor}Kalimdor{/link}.]=],
		},
	},
})

Translate("esMX", "darkspear-islands", {
	title = "Darkspear Islands",
	sections = {
		{
			title = "Resumen",
			text = [=[Las Darkspear Islands se encuentran frente a la costa de {link:durotar}Durotar{/link}, azotadas por las tormentas del mar abierto. Los trols las tienen por sagradas, pues allí sus espíritus son fuertes, y los {link:darkspear-trolls}Lanza Negra{/link} se reúnen en ellas para sus ceremonias. Ahora la {link:alliance}Alianza{/link} busca un punto de apoyo en las islas, cerca de las costas de la patria orca. Los Lanza Negra y sus aliados de la {link:horde}Horda{/link} no la dejarán quedarse. Entre ruinas, un campamento, una vieja torre y una cala de naufragios, los dos bandos luchan por el control de las islas y de una reliquia sagrada de la tribu.]=],
		},
	},
})

Translate("esMX", "kaltunk", {
	title = "Kaltunk",
	subtitle = "Recibidor de reclutas",
	found = "El Cubil, en el Valle de los Retos",
	hint = [=[Hable con el orco que recibe a los jóvenes reclutas del Valle de los Retos.]=],
	allegiance = "Horda",
	sections = {
		{
			title = "Resumen",
			text = [=[Kaltunk recibe a los jóvenes orcos y trols que alcanzan la mayoría de edad en el {link:valley-of-trials}Valle de los Retos{/link}. Examina a cada uno con ojo crítico y una amplia sonrisa. Sabe que todo recluta sueña con estrangular a un dragón el primer día, y disfruta diciéndoles que empiecen por algo más pequeño. Luego se ríe y los envía a El Cubil.]=],
		},
		{
			title = "Importancia",
			text = [=[Kaltunk es la primera voz de la {link:horde}Horda{/link} que muchos de sus jóvenes oyen jamás. Es quien les dice que por fin tienen edad para luchar por el Jefe de Guerra.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Envía a cada nuevo recluta a {link:gornek}Gornek{/link}, en El Cubil.]=],
		},
	},
	mentions = {
		{ text = "Tu lugar en el mundo" },
	},
	bonds = {
		{ id = "gornek", name = "Gornek", note = "recibe a sus reclutas" },
	},
})

Translate("esMX", "gornek", {
	title = "Gornek",
	subtitle = "Maestro de El Cubil",
	found = "El Cubil, en el Valle de los Retos",
	hint = [=[Hable con el orco que asigna las primeras pruebas en El Cubil.]=],
	allegiance = "Horda",
	sections = {
		{
			title = "Resumen",
			text = [=[Gornek asigna las pruebas del valle. Es brusco y difícil de complacer, y recibe a cada recluta como si la {link:horde}Horda{/link} hubiera caído muy bajo para enviarle semejante material. Aun así, los observa de cerca. Los envía primero contra los jabalíes del valle y después contra sus escórpidos, y enseña que hasta el enemigo más pequeño puede traer la muerte.]=],
		},
		{
			title = "Importancia",
			text = [=[Gornek convierte a los jóvenes en guerreros de la {link:horde}Horda{/link}. Sus elogios son raros, y se recuerdan.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Pone a prueba a los reclutas contra los jabalíes moteados y los escórpidos del valle.
• Envía ayuda al trol herido {link:hana-zua}Hana'zua{/link}.
• Hace recoger las armas abandonadas de los reclutas fracasados y devolverlas al herrero.]=],
		},
	},
	mentions = {
		{ text = "Dientes afilados" },
		{ text = "El aguijón del escórpido" },
		{ text = "Sarkoth, según lo contó {link:hana-zua}Hana'zua{/link}" },
		{ text = "Armas extraviadas" },
	},
	bonds = {
		{ id = "kaltunk", name = "Kaltunk", note = "le envía reclutas" },
		{ id = "zureetha-fargaze", name = "Zureetha Fargaze", note = "comparte su campamento" },
		{ id = "hana-zua", name = "Hana'zua", note = "el trol herido al que ayuda" },
	},
})

