		{ id = "gornek", name = "Gornek", note = "comparte su campamento" },
	},
})

Translate("esMX", "hana-zua", {
	title = "Hana'zua",
	subtitle = "Cazador herido de los Lanza Negra",
	found = "La meseta al sur de El Cubil",
	hint = [=[Encuentre al trol herido que yace en la meseta al sur de El Cubil.]=],
	allegiance = "Trols Lanza Negra",
	sections = {
		{
			title = "Resumen",
			text = [=[Hana'zua es un joven trol que salió a cazar escórpidos en el {link:valley-of-trials}Valle de los Retos{/link} y encontró uno mucho más grande que los demás. Asestó a la bestia un fuerte golpe en la pinza, pero su aguijón le abrió una herida profunda en el pecho. Yace herido en la meseta, demasiado débil para volver andando a El Cubil, y más preocupado por su honor que por su herida. Si ha de morir, quiere al menos saber que su enemigo murió antes.]=],
		},
		{
			title = "Importancia",
			text = [=[Hana'zua muestra el orgullo de los {link:darkspear-trolls}Lanza Negra{/link}. No pide ayuda para salvar su vida, sino para ver muerto a su enemigo.]=],
		},
		{
			title = "Hazañas",
