	aliases = { "Daelin", "almirante Proudmoore" },
	sections = {
		{
			title = "Resumen",
			text = [=[Daelin Proudmoore fue el lord almirante de {link:kul-tiras}Kul Tiras{/link} y el padre de {link:jaina-proudmoore}Jaina Proudmoore{/link}. En la {link:second-war}Segunda Guerra{/link} sus flotas dominaron los mares para la {link:alliance}Alianza{/link}, y se convirtió en uno de los grandes héroes de la humanidad. Nunca perdonó a los orcos aquella guerra. Cuando supo que se habían asentado en las costas de {link:kalimdor}Kalimdor{/link}, vino con una armada para destruirlos, y murió en el intento.]=],
		},
		{
			title = "Importancia",
			text = [=[La guerra de Daelin fue la primera gran amenaza para la joven nación de {link:durotar}Durotar{/link}. Su muerte trazó una línea entre padre e hija, y entre dos maneras de ver a los orcos: como un pueblo capaz de cambiar, o como monstruos que nunca lo harían. Sus hombres aún ocupan el {link:tiragarde-keep}Fuerte de Tiragarde{/link} en su nombre.]=],
		},
		{
			title = "El almirante de la Alianza",
			text = [=[{link:kul-tiras}Kul Tiras{/link} era un reino de marineros, y la casa Proudmoore dirigía sus flotas. Cuando la {link:horde}Horda{/link} marchó hacia el norte tras la {link:first-war}Primera Guerra{/link}, Daelin llevó su armada a la {link:alliance}Alianza{/link} de {link:lordaeron}Lordaeron{/link}. Sus barcos combatieron a las flotas orcas en mar abierto y llevaron a los ejércitos de la Alianza de costa en costa. Kul Tiras pagó caro en barcos y en hombres. Daelin recordó ese precio el resto de su vida.]=],
		},
		{
			title = "La armada",
			text = [=[Tras la {link:third-war}Tercera Guerra{/link}, su hija {link:jaina-proudmoore}Jaina{/link} condujo a los supervivientes de {link:lordaeron}Lordaeron{/link} al oeste, a {link:kalimdor}Kalimdor{/link}, y construyó la ciudad de {link:theramore-isle}Theramore{/link}. Allí hizo la paz con {link:thrall}Thrall{/link}. Daelin no quiso aceptarla. Navegó a Kalimdor con una gran flota, levantó el {link:tiragarde-keep}Fuerte de Tiragarde{/link} en la costa de {link:durotar}Durotar{/link} e hizo la guerra a los orcos y a los trols de las {link:echo-isles}Islas del Eco{/link}. La {link:horde}Horda{/link} respondió. Sus guerreros rompieron el fuerte, y al final llevaron la lucha hasta los mismos muros de Theramore. Jaina se hizo a un lado. En los combates, el almirante murió.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirigió la armada de {link:kul-tiras}Kul Tiras{/link} en la {link:second-war}Segunda Guerra{/link}.
• Levantó el {link:tiragarde-keep}Fuerte de Tiragarde{/link} en las costas de {link:durotar}Durotar{/link}.
• Hizo la guerra a la {link:horde}Horda{/link} desafiando la paz de su hija.
• Dejó órdenes para una guerra que continuaría tras su muerte.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito aquí de la vida de Daelin antes de las guerras. Esta entrada recoge solo lo que revelan las historias y sus propias órdenes.]=],
		},
	},
	chapters = {
		{
			title = "Las órdenes del almirante",
			hint = [=[Lea las órdenes selladas que se guardan en el Fuerte de Tiragarde.]=],
			text = [=[Entre las pertenencias del teniente {link:lieutenant-benedict}Benedict{/link} había un viejo sobre con el sello del almirante. Contenía órdenes escritas antes de que Daelin partiera de {link:kul-tiras}Kul Tiras{/link}. Mostraban que había trazado bien sus planes, y que más hombres suyos debían seguir a la primera flota hasta {link:durotar}Durotar{/link}. Los orcos de {link:razor-hill}Cerrotajo{/link} leyeron en ellas una advertencia sencilla: el almirante estaba muerto, pero su guerra no.]=],
